export function normalizeAgreement(v){const money=(x,label)=>{if(x===''||x==null)return null;const n=Number(String(x).replace(',','.'));if(!Number.isFinite(n)||n<0||n>1000||Math.abs(n*100-Math.round(n*100))>1e-6)throw Error(label+': Betrag mit höchstens zwei Nachkommastellen zwischen 0 und 1.000 € eingeben.');return Math.round(n*100)};const days=(x,label,required=false)=>{if(x===''||x==null){if(required)throw Error(label+' fehlt.');return null}const n=Number(x);if(!Number.isInteger(n)||n<1||n>365)throw Error(label+': 1 bis 365 ganze Tage eingeben.');return n};const discountEnabled=!!v.discountEnabled,netDays=days(v.netDays,'Zahlungsziel',discountEnabled),discountDays=discountEnabled?days(v.discountDays,'Skontofrist',true):null,discountPercent=discountEnabled?Number(v.discountPercent):null;if(discountEnabled&&(!Number.isFinite(discountPercent)||discountPercent<=0||discountPercent>=100))throw Error('Skonto muss größer als 0 und kleiner als 100 Prozent sein.');if(discountEnabled&&discountDays>netDays)throw Error('Die Skontofrist darf das Zahlungsziel ohne Skonto nicht überschreiten.');return{project:String(v.project||'').trim(),fitterRateCents:money(v.fitterRate,'Monteursatz'),foremanRateCents:money(v.foremanRate,'Obermonteursatz'),netDays,discountEnabled,discountDays,discountPercent};}
export function rateForRole(agreement,role,fallback){const cents=/ober|foreman/i.test(role)?agreement?.foremanRateCents:agreement?.fitterRateCents;return cents==null?fallback:cents/100}
export function discountSettlement(cents,agreement){if(!agreement?.discountEnabled)return{discountCents:0,paymentCents:cents};const discountCents=Math.round(cents*agreement.discountPercent/100);return{discountCents,paymentCents:cents-discountCents};}
export const ALL_PROJECTS='Alle Projekte (Standardsatz)';
// A project agreement wins; the company's rate for all projects is the fallback.
export function pickAgreement(agreements,companyId,projectId,label){const own=agreements.filter(a=>a.companyId===companyId);return own.find(a=>!a.allProjects&&(projectId&&a.projectId?a.projectId===projectId:a.project===label))??own.find(a=>a.allProjects)}
